-- เปลี่ยนรูปไฟโตพาวเดอร์อะเซโรล่า-ซี เป็นรูปพื้นขาว
UPDATE "product_images" SET "content_type" = 'image/jpeg', "data" = '', "updated_at" = now()
WHERE "product_id" IN (SELECT "id" FROM "products" WHERE "name" = 'ไฟโตพาวเดอร์อะเซโรล่า-ซี');
--> statement-breakpoint
UPDATE "products" SET "image_updated_at" = now() WHERE "name" = 'ไฟโตพาวเดอร์อะเซโรล่า-ซี';
